/** The triage scale and its algorithm — GET /api/v1/er/triage-scale (who may call: holders of er.visit.view). */
export function getScale(query?: { include_inactive?: boolean }): Promise<ErTriageScaleOut> {
  return api<ErTriageScaleOut>("GET", withQuery(`/er/triage-scale`, query), undefined);
}

/** Change a triage level — PATCH /api/v1/er/triage-scale/levels/{level} (who may call: holders of er.triage.configure). */
export function updateLevel(level: number, body: TriageLevelIn): Promise<ErTriageLevelOut> {
  return api<ErTriageLevelOut>("PATCH", `/er/triage-scale/levels/${level}`, body);
}

/** Add a danger sign or a vital-sign limit — POST /api/v1/er/triage-scale/signs (who may call: holders of er.triage.configure). */
export function addSign(body: TriageSignIn): Promise<ErTriageDiscriminatorOut> {
  return api<ErTriageDiscriminatorOut>("POST", `/er/triage-scale/signs`, body, { idempotent: true });
}

/** Change or retire a danger sign or vital-sign limit — PATCH /api/v1/er/triage-scale/signs/{discriminator_id} (who may call: holders of er.triage.configure). */
export function updateSign(discriminator_id: number, body: TriageSignUpdateIn): Promise<ErTriageDiscriminatorOut> {
  return api<ErTriageDiscriminatorOut>("PATCH", `/er/triage-scale/signs/${discriminator_id}`, body);
}

/** The written triage algorithm (A4) — GET /api/v1/er/triage-scale/print-payload (who may call: holders of er.visit.view). */
export function printScale(): Promise<PrintOut_ErTriagePrintFieldsOut_> {
  return api<PrintOut_ErTriagePrintFieldsOut_>("GET", `/er/triage-scale/print-payload`, undefined);
}

/** The written triage algorithm as a PDF — GET /api/v1/er/triage-scale/pdf (who may call: holders of er.visit.view). */
export function scalePdf(): Promise<unknown> {
  return api<unknown>("GET", `/er/triage-scale/pdf`, undefined);
}
